INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-05' FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Real-time DJP clearance via Coretax since 31 December 2025, following a phased e-Faktur mandate that reached nationwide coverage in 2016', 'This deep-dive page reflects publicly available DJP guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Confirm current requirements directly with DJP or an Indonesian tax adviser before relying on this page for compliance decisions.', 'Indonesia''s e-Faktur Pajak system required electronic VAT invoices in stages from 2014, reaching full nationwide coverage by 1 July 2016. DJP''s Coretax platform launched 1 January 2025 and became fully enforced from 31 December 2025, shifting Indonesia to a genuine real-time clearance model where DJP approval is a legal precondition for a valid invoice.', 'Coretax invoices are created in XML and uploaded for real-time validation by DJP; once approved, the invoice is issued to the buyer as a QR-coded PDF carrying an auto-generated Tax Invoice Serial Number (Nomor Seri Faktur Pajak, NSFP). Businesses can access Coretax through its web portal, a desktop client, or a Host-to-Host (H2H) integration for enterprise accounting systems. Paper invoices are only permitted during confirmed system outages -- otherwise every tax invoice must move through this electronic, DJP-validated process.', 'Indonesia''s e-invoicing mandate is close to universal: every VAT-registered taxpayer (Pengusaha Kena Pajak, PKP) is in scope, covering domestic B2B and B2G taxable supplies, export invoices (issued as zero-rated VAT invoices), and corrective documents such as credit notes, debit notes, and cancellations. There''s no small-business or sector carve-out comparable to some other countries this tracker covers -- registration as a PKP is itself what brings a business into scope.', 'Because Coretax''s full enforcement is recent -- effective only from 31 December 2025 -- most PKP still have real implementation work ahead, whether that''s confirming their existing e-Faktur setup properly migrated or building out a first Coretax-connected invoicing workflow.', 'Indonesia backs its e-invoicing and VAT reporting rules with real, sourced penalties, ranging from the loss of input tax credit for a late-uploaded invoice to fines that scale with the size of an underpayment.', 'Indonesia has required electronic VAT invoices since 2014, reaching nationwide e-Faktur coverage by 1 July 2016. DJP''s Coretax platform launched 1 January 2025, and PER-11/PJ/2025 moved the invoice upload deadline to the 20th of the following month. From 31 December 2025, Coretax became fully enforced: DJP clearance is now a legal precondition for a valid invoice, not a post-creation check. Uncleared invoices cannot support VAT input tax deductions, and misreporting can draw penalties up to 100% of underpaid VAT.', '🇮🇩' FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Indonesia';
