INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Invoice creation", "XML, generated through Coretax or Coretax-connected software"], ["Validation", "Real-time validation by DJP before the invoice is legally issued"], ["Delivery format", "QR-coded PDF, carrying an auto-generated Tax Invoice Serial Number (NSFP)"], ["Access channels", "Coretax web portal, desktop client, or Host-to-Host (H2H) integration for enterprise systems"]]', 'Paper invoices remain permitted only during confirmed system outages -- treat electronic issuance through one of Coretax''s channels as the default, not the exception.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer registration", "Pengusaha Kena Pajak (PKP) -- VAT registration with DJP is the trigger for e-invoicing scope"], ["Coretax account", "Registered and activated through the Coretax DJP portal"], ["Serial number", "Nomor Seri Faktur Pajak (NSFP), auto-generated by Coretax on approval"], ["Governing body", "Direktorat Jenderal Pajak (DJP) -- Directorate General of Taxes, Ministry of Finance"]]', 'Foreign businesses that register for Indonesian VAT come into scope on the same basis as domestic PKP once registered.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content & retention', '[["Core invoice fields", "Issuer/buyer tax identification, invoice date, itemized goods/services and VAT amounts, NSFP"], ["Legal basis", "DJP regulations under Indonesia''s VAT Law framework, including PMK 131/Tahun 2024"], ["Corrective documents", "Credit notes, debit notes, and cancellations must also be processed through Coretax"], ["Retention", "Consistent with Indonesia''s general bookkeeping/tax document retention rules under the General Tax Provisions Law (typically 10 years) -- confirm the current period with DJP or a local adviser"]]', 'Don''t treat PMK 131/Tahun 2024 as the sole legal basis for every rule here -- DJP has layered multiple regulations (KEP-54/PJ/2025, PER-11/PJ/2025, PER-8/PJ/2025) on top of the core VAT Law framework.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The Coretax clearance flow', 'A tax invoice moves through this sequence under Coretax -- DJP validation now happens before the invoice is legally valid, not after:', 'This is a genuine clearance model: unlike the old e-Faktur system''s post-creation checks, an invoice has no legal effect -- and cannot support the buyer''s VAT input tax credit -- until DJP clears it.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Seller generates the tax invoice in XML through Coretax (web portal, desktop client, or Host-to-Host integration)');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice uploaded to Coretax for real-time DJP validation');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'DJP validates the invoice and assigns a Tax Invoice Serial Number (NSFP)');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Coretax issues a QR-coded PDF version of the cleared invoice');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice is legally valid and delivered to the buyer -- only now can it support the buyer''s VAT input tax credit');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s mandatory today, by layer', '[["Nationwide e-Faktur issuance", "All PKP, since 1 July 2016"], ["Coretax real-time clearance", "All PKP, mandatory since 31 December 2025"], ["Large-taxpayer H2H/Desktop channels", "Still permitted, but now feed into Coretax''s clearance rather than operating independently"], ["Paper invoices", "Only permitted during confirmed system outages"]]', 'It''s worth being precise about which layer applies to you: Indonesia''s e-invoicing mandate has been genuinely universal since 2016, but the clearance requirement -- DJP approval before an invoice is valid -- only became fully enforced from 31 December 2025.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who must comply', '[["PKP registration", "Any business exceeding Indonesia''s VAT registration threshold must register as a PKP and comply"], ["Domestic B2B and B2G", "Fully in scope -- taxable supplies of goods and services"], ["Export invoices", "In scope, issued as zero-rated VAT invoices"], ["Corrective documents", "Credit notes, debit notes, and cancellations must also be processed through Coretax"]]', 'There''s no general small-business exemption from Coretax comparable to some other tracked countries -- PKP registration itself is the trigger.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💰 Miss the 20th-of-the-month upload deadline, lose the VAT credit', NULL, NULL, 'Since PER-11/PJ/2025 (22 May 2025), tax invoices must be uploaded to Coretax by the 20th of the month following issuance. Miss that deadline and the buyer loses eligibility to claim VAT input tax credit on the invoice -- an immediate financial consequence for the buyer, not just an administrative slip by the seller.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Fines for failing to issue e-invoices and for late VAT returns', NULL, NULL, 'Failure to issue e-invoices as required triggers administrative fines. Separately, late filing of the periodic VAT return (SPT Masa PPN) carries a fixed IDR 500,000 fine -- a routine but real cost of missing a filing deadline, independent of any invoice-level penalty.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔒 Uncleared invoices can''t support input tax credit', NULL, NULL, 'Since Coretax became fully enforced on 31 December 2025, DJP clearance is a legal precondition for a valid tax invoice. An invoice DJP hasn''t cleared cannot support the buyer''s VAT input tax deduction, and misreporting or underpayment of VAT can draw penalties of up to 100% of the underpaid amount -- a real, meaningful exposure, not a nominal one.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Late filing of the periodic VAT return (SPT Masa PPN)', 'IDR 500,000 (fixed)', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Misreporting or underpayment of VAT', 'Up to 100% of the underpaid VAT amount', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your PKP registration and Coretax account are active', 'Every VAT-registered taxpayer (PKP) needs an active Coretax account -- confirm yours is registered and accessible before relying on it for invoice issuance.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Move your invoicing workflow onto a Coretax-connected channel', 'Whether through the web portal, the desktop client, or a Host-to-Host (H2H) integration, confirm your invoicing software actually submits to Coretax rather than relying on a standalone legacy process.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Upload every invoice to Coretax before the 20th of the following month', 'PER-11/PJ/2025 set this as the hard deadline -- missing it costs the buyer their VAT input tax credit, so treat it as a compliance deadline, not a soft target.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build a real-time DJP-clearance check into your invoice issuance process', 'Since 31 December 2025, an invoice has no legal effect until DJP clears it -- confirm your process waits for that clearance before treating an invoice as final.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your accounts-payable process rejects supplier invoices without valid Coretax clearance', 'A supplier invoice without DJP clearance and a valid NSFP cannot support your VAT input tax credit -- build that check into your AP workflow, not just your own sales process.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Keep a paper-invoice contingency plan limited strictly to confirmed system outages', 'Paper invoicing remains permitted only during genuine Coretax outages -- don''t let it become a routine workaround for slow onboarding or unresolved technical issues.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://coretaxdjp.pajak.go.id/', 0 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Coretax DJP — real-time e-invoice clearance and VAT operations platform');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.pajak.go.id/', 1 FROM countries WHERE name_en = 'Indonesia';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Direktorat Jenderal Pajak (DJP) — Directorate General of Taxes');
